package com.bomboniere.estoque.controller;
import com.bomboniere.estoque.dto.*; import com.bomboniere.estoque.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/produtos")
public class ProdutoController { private final ProdutoService produtos;private final MovimentacaoService movimentacoes;public ProdutoController(ProdutoService p,MovimentacaoService m){produtos=p;movimentacoes=m;}@GetMapping public List<ProdutoResponse> listar(@RequestParam(required=false)String nome,@RequestParam(required=false)Long categoriaId){return produtos.listar(nome,categoriaId);}@GetMapping("/estoque-baixo")public List<ProdutoResponse> baixo(){return produtos.estoqueBaixo();}@GetMapping("/{id}")public ProdutoResponse buscar(@PathVariable Long id){return produtos.buscar(id);}@PostMapping public ResponseEntity<ProdutoResponse> criar(@Valid @RequestBody ProdutoRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(produtos.criar(r));}@PutMapping("/{id}")public ProdutoResponse atualizar(@PathVariable Long id,@Valid @RequestBody ProdutoRequest r){return produtos.atualizar(id,r);}@DeleteMapping("/{id}")public ResponseEntity<Void> excluir(@PathVariable Long id){produtos.excluir(id);return ResponseEntity.noContent().build();}@PostMapping("/{id}/entrada")public ResponseEntity<MovimentacaoResponse> entrada(@PathVariable Long id,@Valid @RequestBody MovimentacaoRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(movimentacoes.entrada(id,r));}@PostMapping("/{id}/saida")public ResponseEntity<MovimentacaoResponse> saida(@PathVariable Long id,@Valid @RequestBody MovimentacaoRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(movimentacoes.saida(id,r));}}
